(()=>{'use strict';
const params=new URLSearchParams(location.search),screen=params.get('screen')||'U02',actorId=params.get('as')||RolePolicy.defaultActor(screen),actor=RolePolicy.get(actorId),examId=params.get('exam')||'EX1',preview=params.has('preview');
const root=document.getElementById('app'),subjects=YF.subjects;let feedback='',feedbackType='',saving=false,renderedState='';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const context=()=>YF.view(actorId,examId),exam=()=>context().exam,personId=()=>actor.studentId||params.get('person')||exam()?.current||exam()?.lastEnded||exam()?.roster[0],qValue=()=>/^[012]$/.test(params.get('q'))?+params.get('q'):0;
window.getWalkContext=()=>({view:context(),params:Object.fromEntries(params),actorId,screen,examId});
window.getPageExplanation=()=>PageGuides.describe({screen,actorId,examId,params,view:context()});
const name=id=>{const person=context().people.find(p=>p.id===id);return person?(actor.group==='teacher'?person.campus+' · '+person.name:person.name):id;};
const staffName=id=>context().staff[id]?.name||'尚未安排';
function url(id,extra={}){const q=new URLSearchParams({screen:id,as:actorId,exam:examId,...extra});if(YF.walk)q.set('walk',YF.walk);if(params.get('rev'))q.set('rev',params.get('rev'));if(YF.fixture)q.set('fixture',YF.fixture);if(preview)q.set('preview','1');return 'page.html?'+q;}
const link=(id,label,extra={},kind='')=>RolePolicy.canOpen(actorId,id)?`<a class="button ${kind}" href="${url(id,extra)}">${label}</a>`:'';
const button=(label,command,payload={},kind='',disabled=false)=>`<button type="button" class="${kind}" data-command="${command}" data-payload="${esc(JSON.stringify(payload))}" ${disabled?'disabled':''}>${label}</button>`;
const action=(label,value,payload={},kind='',disabled=false)=>`<button type="button" class="${kind}" data-ui="${value}" data-payload="${esc(JSON.stringify(payload))}" ${disabled?'disabled':''}>${label}</button>`;
const tag=(s,kind='')=>`<span class="tag ${kind}">${s}</span>`,notice=(s,kind='')=>`<div class="banner ${kind}" role="status">${s}</div>`;
const heading=(title,desc='',controls='')=>`<div class="page-heading"><div><div class="eyebrow">${esc(exam()?.name||'艺风考试')}</div><h1>${title}</h1>${desc?`<p>${desc}</p>`:''}</div><div class="actions">${controls}</div></div>`;
const field=(id,label,value='',type='text')=>`<div class="field"><label for="${id}">${label}</label><input id="${id}" name="${id}" type="${type}" value="${esc(value)}" ${type==='text'?'maxlength="100"':''}></div>`;
const select=(id,label,values,value)=>`<div class="field"><label for="${id}">${label}</label><select id="${id}" name="${id}">${values.map(([v,l])=>`<option value="${v}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`).join('')}</select></div>`;
const check=(id,text)=>`<label class="device-check"><input type="checkbox" id="${id}" name="${id}"><span>${text}</span></label>`;
const reason=(id='reason',label='原因或处理说明')=>`<label for="${id}">${label}</label><textarea id="${id}" name="${id}" maxlength="500" required placeholder="请填写具体说明"></textarea>`;
const form=(id,html,label='保存',payload={})=>`<form data-form="${id}" data-payload="${esc(JSON.stringify(payload))}">${html}<div class="actions"><button type="submit" class="primary">${label}</button></div></form>`;
const empty=(title,desc,controls='')=>`<section class="panel empty"><h2>${title}</h2><p>${desc}</p><div class="actions">${controls}</div></section>`;
const table=(heads,rows)=>`<div class="table-scroll"><table><thead><tr>${heads.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`;
const row=cells=>`<tr>${cells.map(c=>`<td>${c}</td>`).join('')}</tr>`;
const pendingRule=(text,confirm=false)=>notice('演示假设 · '+text+'；正式决定权与规则待确认。','warning')+(confirm?check('demoConfirmed','我了解本次仅用于体验上述演示流程'): '');
const video=(label,duration=ExamSpec.durations[qValue()])=>`<div class="video"><label>${label}</label><div class="person" aria-hidden="true"></div>${action('▶','play',{},'',false)}<small>画面示意 · 无真实音视频</small></div><div class="playbar"><span>00:00</span><div class="track"></div><span>${ExamSpec.time(duration)}</span></div>`;
const status=e=>({draft:'准备草稿',ready:'岗位已开放',live:'执行中',archived:'历史记录'}[e.status]||e.status);
const taskState=r=>!r?'暂无当前学员':r.attendance==='absent'?'已登记缺考':r.onsiteEnded?'本位现场已结束':r.technicalSubmitted?'技术检查已提交，等待监考放行':r.handoff==='accepted'?'场内已接收':r.handoff==='pending'?'等待场内接收':r.drawPending?'抽题待查询':r.draw?'候考，题套已确认':r.checkin?'已签到，待抽题':'待本人签到';
const uploadState=f=>!f?'尚无文件':f.abnormal?'异常片段，待处置':({none:'本地已保存，待检查',queued:'等待上传',uploading:'上传中，待查询',failed:'上传失败，原文件保留',received:f.checked?'后台收到且核验通过':'后台收到，待核验'}[f.upload]);
const exceptionType={material:'视频问题核验',retake:'补录申请',replace:'有效视频替换',absence:'缺考登记',reorder:'候考顺序调整',redraw:'重新抽题',return:'恢复候考'};
const decisionStatus={pending:'待处理',executing:'待重新录制',awaiting_material:'待材料复核',resolved:'处理完成',rejected:'已退回',cancelled:'已撤回',accepted:'已接收',applied:'新分数已生效'};
const navs={admin:[['U02','考试列表'],['U03','本场总览'],['W13','评分分工'],['X01','异常处置'],['W24','改分申请'],['W10','整体评卷'],['W07','核对发布'],['W19','账号岗位']],academic:[['U02','考试列表'],['W01','本场准备'],['W11','名单导入'],['W12','安排核对'],['W03','整套试卷'],['W04','材料核对'],['X01','问题与回执']],teacher:[['W05','我的评卷'],['W16','本科队列'],['W17','完成记录'],['X01','本人问题'],['W24','本人改分']],invigilator:[['M00','岗位任务'],['M01','候考名单'],['M04','交接回执'],['X01','问题与处理结果']],recorder:[['A00','岗位任务'],['A04','当前学员'],['A03','本机文件'],['X01','问题与处理结果']],student:[['S00','我的考试'],['S05','我的成绩']]};
function trail(){const d=JourneyData[actor.group];return d?`<div class="journey-trail"><span>${d.title} · ${d.scope}</span><nav>${d.steps.map(([id,label])=>`<a href="${url(id,{q:qValue()})}" class="${screen===id?'active':''}">${label}</a>`).join('<b>›</b>')}</nav></div>`:'';}
function extraNav(){const list=(JourneyData[actor.group]?.tools||[]).filter(([id])=>PageBuckets.get({id})==='exception');return list.length?`<details class="extra-nav"><summary>异常与问题处理</summary>${list.map(([id,label])=>link(id,label)).join('')}</details>`:'';}
function shell(html){const v=context(),mobile=['student','recorder','invigilator'].includes(actor.group),e=v.exam;
 const info=(e?.status==='archived'?notice('这场考试已归档，仅查看本人范围内的历史记录。'):'')+(v.storageError?notice('本机存储不可用，当前改动仅临时保留。请保持本页并恢复浏览器存储。','error'):'')+(v.faults.offline?notice('当前离线。已领录制任务与本机输入保留，远端操作待连接恢复。','warning'):'')+(feedback?notice(esc(feedback),feedbackType):'');
 const choose=`<div class="context-bar"><span>当前考试</span><select id="exam-switch" aria-label="切换当前考试">${!e?'<option value="" selected disabled>从下方选择本人场次</option>':''}${v.exams.map(x=>`<option value="${x.id}" ${x.id===examId?'selected':''}>${esc(x.name)} · ${x.date}</option>`).join('')}</select>${e?tag(status(e)):''}</div>`;
 if(screen==='A02')return `<div class="record-layout"><header class="record-header"><img src="assets/yifeng-logo.png" alt="艺风传媒"><div class="record-meta">${esc(e?.name||'录制任务')} / ${esc(e?.room||'')}<br>${actor.name} · 手机与大屏同画面</div></header><main id="main" class="record-body" tabindex="-1">${info}${html}</main></div>`;
 if(mobile)return `<div class="phone-layout"><header class="phone-top"><img src="assets/yifeng-logo.png" alt="艺风传媒"><div><strong>${actor.label}</strong><br><span class="muted">${actor.name}</span></div></header><main id="main" class="phone-main" tabindex="-1">${info}${choose}${trail()}${html}${extraNav()}</main><nav class="student-nav">${navs[actor.group].slice(0,3).map(([id,l])=>link(id,l,{},screen===id?'active':'')).join('')}</nav><footer class="phone-footer">${['recorder','invigilator'].includes(actor.group)&&!YF.walk?action('切换本人兼任岗位','switch-post'):''}<p>艺风传媒 · ${actor.label}工作区</p></footer></div>`;
 return `<div class="layout"><aside class="sidebar"><div class="brand"><img src="assets/yifeng-logo.png" alt="艺风传媒"><small>${actor.label}<br>工作区</small></div><nav class="side-nav">${navs[actor.group]?.filter(([id])=>PageBuckets.get({id})==='normal').map(([id,l])=>`<a class="${id===screen?'active':''}" href="${url(id,{q:qValue()})}">${l}</a>`).join('')||''}${extraNav()}</nav><div class="sidebar-bottom">${actor.name}<br>按考试与本人岗位接续</div></aside><div class="workarea"><header class="topbar"><strong>艺风考试 / ${actor.label}工作区</strong><span>${actor.name}</span></header><main id="main" class="content" tabindex="-1">${info}${choose}${trail()}${html}</main></div></div>`;
}
function go(id,extra={}){location.href=url(id,extra);}
function note(message,kind=''){feedback=message;feedbackType=kind;const body=document.querySelector('dialog[open] .dialog-feedback');if(body)body.innerHTML=notice(esc(message),kind);else render();document.getElementById('announcer').textContent=message;}
function modal(title,body){document.querySelector('dialog')?.close();const d=document.createElement('dialog');d.className='dialog';d.innerHTML=`<div class="dialog-body"><h2>${title}</h2><div class="dialog-feedback"></div>${body}<div class="actions">${action('关闭','close-dialog')}</div></div>`;document.body.append(d);d.addEventListener('close',()=>d.remove());d.showModal();d.querySelector('input,textarea,button')?.focus();}
function close(){document.querySelector('dialog')?.close();}
function execute(command,payload={}){const result=YF.run(actorId,command,{examId,...payload});if(!result.ok){note(result.message,'warning');return result;}close();feedback=result.message;feedbackType='';if(result.target)go(result.target,{exam:result.examId||examId,...(payload.person?{person:payload.person}:{}),...(payload.q!==undefined?{q:payload.q}:{})});else note(result.message);return result;}
function staffAssigned(){const e=exam();return e&&e.staff?.[actor.group]===actor.staffId&&context().staff[actor.staffId]?.active;}
const scoreKey=(q,p)=>`${q}-${actor.teacher}-${p}`;

const totalFor=(id)=>ExamSpec.total(subjects.map((_,q)=>YF.mean(examId,q,id)));
const totalBanner=()=>notice(ExamSpec.totalNote,'warning');
function rubric(q){return `<section class="panel"><h2>${subjects[q]} · 评分标准</h2>${tag('标准示例 · 待教研确认','warning')}<dl class="rubric-list">${ExamSpec.rubrics[q].map(([a,b])=>`<dt>${a}</dt><dd>${b}</dd>`).join('')}</dl><p class="fine">当前仅提供观察维度，不分配维度权重，不把示例当作正式评分细则。</p></section>`;}
function ownBands(q){const e=exam(),values=Object.entries(e.scores).filter(([k])=>k.startsWith(q+'-')).map(([,s])=>s.value),bands=[[0,60,'低于60'],[60,80,'60–79.99'],[80,90,'80–89.99'],[90,101,'90–100']];return `<section class="panel"><h2>本人本科评分分布</h2><p class="fine">只统计本人已保存评分。以下分段为展示示例，没有人数配额，不限制独立判断。</p><div class="band-grid">${bands.map(([min,max,label])=>{const n=values.filter(v=>v>=min&&v<max).length;return `<div><span>${label}</span><strong>${n}人</strong><small>${values.length?(n/values.length*100).toFixed(0):0}%</small></div>`}).join('')}</div><p>已保存 ${values.length} 份；其他评委原始分与分差仅管理员可见。</p></section>`;}
function spread(q,p){const e=exam(),v=e.assignments[q].map(t=>e.scores[`${q}-${t}-${p}`]?.value);if(!v.length||!v.every(Number.isFinite))return '待齐评';const d=Math.max(...v)-Math.min(...v),limit=e.scorePolicy?.differenceThreshold;return d.toFixed(2)+(limit!==null&&limit!==undefined&&d>limit?' · 超示例阈值，建议核对':limit===null||limit===undefined?' · 提醒阈值未配置':' · 未超示例阈值');}
function prepPanel(r){if(!r.draw||r.drawPending)return '';const left=r.prepStarted?Math.max(0,900-(Date.now()-r.prepStarted)/1000):0;return `<section class="panel"><h2>统一备稿 · 15分钟</h2><div class="timer prep-timer" data-prep-start="${r.prepStarted||0}" aria-label="备稿剩余时间">${ExamSpec.time(left)}</div><p class="prep-state" role="status">${left>0?'备稿中：请在手机上阅读三科题目。':'备稿已到时，请等待监考叫号，不自行入场。'}</p><p class="fine">刷新与返回保持同一截止时间。演示从抽题结果生成时开始计时；正式起算与提前入场细则待确认。</p></section>`;}
function studentProgress(r,e){const media=r.mediaProgress||[],prepDone=!!r.draw&&!r.drawPending&&(!r.prepStarted||Date.now()-r.prepStarted>=900000||r.handoff!=='idle');const steps=[
 ['本人签到',r.checkin,r.checkin?'已确认':'到本人考场扫码并核对信息','S03'],
 ['三科一次抽题',r.draw&&!r.drawPending,r.draw?(r.drawPending?'查询原结果，不重新抽题':r.draw+'号-v1已锁定'):'一次抽取完整题组','D01'],
 ['15分钟备稿',prepDone,prepDone?(r.prepStarted&&Date.now()-r.prepStarted>=900000?'15分钟备稿已到时，原题组与起点保留':'已进入后续现场环节，原备稿记录保留'):r.draw&&!r.drawPending?'备稿中，查看手机倒计时':'抽题后开始统一备稿','D01'],
 ['候考与入场',r.handoff==='accepted'||r.onsiteEnded,r.onsiteEnded?'已完成入场与现场考试':r.handoff==='pending'?'等待录制员接收':r.handoff==='accepted'?'已接收，请按引导考试':'等待监考叫号；签到不等于入场','S01'],
 ...subjects.map((n,q)=>[n+'录制',!!media[q]?.saved,media[q]?.saved?'本地已保存':r.stage==='recording'&&r.subject===q?'正在录制 · '+ExamSpec.time(ExamSpec.durations[q]):'等待录制 · 限时'+ExamSpec.time(ExamSpec.durations[q]),null]),
 ['离场前技术核验',!!r.technicalSubmitted&&!r.technicalBlocked,r.technicalBlocked?'视频问题待工作人员处理':r.onsiteEnded?'三科技术检查已确认，监考已放行':r.technicalSubmitted?'录制员已提交，等待监考确认':'录制员检查三科音画、时长和保存结果',null],
 ['监考放行 · 考试完成',!!r.onsiteEnded,r.onsiteEnded?'监考已放行，现场考试完成':'技术核验后由监考确认放行',null],
 ['上传与评分材料核验',media.length===3&&media.every(f=>f.materialChecked),media.length===3&&media.every(f=>f.materialChecked)?'三科评分材料均已核验':media.length===3&&media.every(f=>f.upload==='received')?'后台收到，教务核验中':'原文件继续上传；无需学生重复操作',null],
 ['评阅与成绩发布',e.publications.length>0,e.publications.length?'已发布本人结果':'老师独立评阅，等待管理员核对发布','S02']
 ];const current=steps.findIndex(x=>!x[1]);return `<section class="panel"><h2>当前：${current<0?'本次流程已完成':steps[current][0]}</h2><p>${current<0?'可查看本人成绩。':steps[current][2]}</p><ol class="progress-list detailed-progress">${steps.map(([label,done,text,to],i)=>`<li class="${done?'done':i===current?'current':'pending'}" ${i===current?'aria-current="step"':''}><span class="progress-number">${done?'✓':i+1}</span><div><strong>${label}</strong><p>${text}</p>${to?link(to,done?'查看记录':i===current?'前往这一步':'查看状态'):''}</div></li>`).join('')}</ol></section>`;}

function pages(){const e=exam(),v=context(),p=personId(),r=e?.records?.[p],q=qValue();return {
 U01(){return actor.home==='U02'?this.U02():this[actor.home]()},
 U02(){const list=v.exams.filter(x=>actor.group!=='student'||x.status!=='draft');return `${heading('考试与我的任务','每场独立保存名单、现场记录、文件与成绩。',['admin','academic'].includes(actor.group)?link('U04','＋ 新建考试',{},'primary'):'')}<div class="three-col">${list.map(x=>`<section class="taskcard">${tag(status(x))}<h2>${esc(x.name)}</h2><p>${x.date} · ${esc(x.room)}</p>${link(['admin','academic'].includes(actor.group)?'U03':actor.home,'进入本场',{exam:x.id},'primary')}</section>`).join('')}</div>${!list.length?empty('暂时没有本人的考试任务','本场准备完成且分配给本人后，会出现在这里。'):''}`},
 U04(){return `${heading('新建考试','先建立独立场次，再准备名单、题套与岗位。',link('U02','返回考试列表'))}<section class="panel">${form('create-exam',`<div class="form-grid">${field('name','考试名称','第二轮播音模拟考')}${field('date','考试日期','2026-10-29','date')}${select('room','考场',[['03考场','03考场'],['02考场','02考场']],'03考场')}${select('copyFrom','参考已存配置',[['','从空白准备'],...v.exams.map(x=>[x.id,x.name])],'')}</div>${notice('参考配置只带岗位、科目分工与题套选择；名单、签到、视频、评分和发布记录均重新产生。')}`,'建立本场并继续准备')}</section>`},
 U03(){const pending=e.exceptions.filter(x=>['pending','executing','awaiting_material'].includes(x.status)).length,done=Object.values(e.records).filter(x=>x.onsiteEnded).length;return `${heading(esc(e.name)+' · 总览',e.date+' / '+e.room,link('U02','切换考试'))}<div class="three-col"><div class="stat"><small>场次状态</small><strong>${status(e)}</strong></div><div class="stat"><small>现场已结束</small><strong>${done} / ${e.roster.length}</strong></div><div class="stat"><small>待跟进异常</small><strong>${pending}</strong></div></div><section class="panel"><h2>${e.status==='draft'?'先完成本场准备':e.status==='archived'?'本场历史记录':'本场任务已开放'}</h2><div class="actions">${link('W01','打开本场准备',{},'primary')}${link('W04','核对本场材料')}${link('X01','查看异常与回执')}${link('W10','查看整体评卷')}${link('W07','核对本场成绩')}</div></section>${notice(e.status==='draft'?'准备完成后开放本场，各岗位从自己的任务列表进入。':e.status==='archived'?'本场已归档，仅供回看已存记录。':'现场、上传、评分、发布分别显示。新建下一场不会清空本场未完任务。')}`},
 W01(){const issues=YF.prepIssues(examId);return `${heading('本场准备','名单、题套与人员核对后，开放本场给各岗位。',link('U03','返回本场总览'))}<div class="two-col"><div><section class="panel"><h2>准备清单</h2>${[['名单与排次',e.roster.length?e.roster.length+'名已导入':'尚未导入','W11'],['整套试卷',e.paperSelected?'17号-v1已选用':'未选定完整套卷','W03'],['岗位与考场',staffName(e.staff.invigilator)+'监考 / '+staffName(e.staff.recorder)+'录制','W12'],['评分分工','每位老师评本科全部学员','W13']].map(([title,desc,id])=>`<div class="listrow"><div><h3>${title}</h3><p>${desc}</p></div>${link(id,'去核对')}</div>`).join('')}<hr>${e.status==='draft'?`${notice(issues.length?'待补齐：'+issues.join('、'):'准备项已齐，可以开放本场。',issues.length?'warning':'')}${button('检查并开放本场','activate-exam',{},'primary',!!issues.length)}`:notice('本场已开放，现用名单与任务记录保留。现场问题按需登记；人员安排由管理员从岗位页查看。')}</section></div><section class="panel"><h2>基本安排</h2>${e.status==='draft'?form('save-exam',`<div class="form-grid">${field('name','考试名称',e.name)}${field('date','考试日期',e.date,'date')}${select('room','考场',[['03考场','03考场'],['02考场','02考场']],e.room)}</div><p class="small muted">时间段：${e.slot}（演示样本）</p>`,'保存本场草稿'):`<dl class="kv"><dt>名称</dt><dd>${esc(e.name)}</dd><dt>日期</dt><dd>${e.date}</dd><dt>考场</dt><dd>${e.room}</dd></dl>`}</section></div>`},
 W11(){if(e.status!=='draft')return `${heading('本场名单记录','本场已开放，查看已导入结果。',link('W12','核对名单与安排',{},'primary'))}<section class="panel">${e.roster.length?table(['学员','机构编号','计划排次'],e.roster.map(id=>row([name(id),YF.students.find(x=>x.id===id).code,e.records[id].seat]))):empty('本场没有已导入学员','返回本场总览查看当前安排。',link('U03','返回总览'))}</section>`;return `${heading('本场名单导入','使用虚构名单体验本场导入与身份核对。',link('W01','返回准备'))}<section class="panel">${e.status!=='draft'?notice('本场已开放，不覆盖已产生的应考记录。'):''}${form('import-roster',`<h2>选择本场应考学员</h2>${YF.students.map(x=>`<label class="device-check"><input type="checkbox" name="people" value="${x.id}" ${e.roster.includes(x.id)?'checked':''} ${e.status!=='draft'?'disabled':''}><span>${x.name} · ${x.code} · ${x.class}</span></label>`).join('')}${check('verified','已按机构编号核对本人，确认名单与本场安排一致')}<p class="fine">演示使用固定样本，不会上传真实名单。未确认的同名账号不自动合并。</p>`,e.status==='draft'?'确认本批导入':'查看已存记录')}<div class="actions">${link('W12','查看本场导入结果')}</div></section>`},
 W02(){return this.W12()},
 W12(){return `${heading('本场安排与导入结果','计划排次和现场候考分别记录。',link('W01','返回准备清单'))}<section class="panel"><h2>本场名单 ${e.roster.length} 人</h2>${e.roster.length?table(['学员','机构编号','计划排次','考场'],e.roster.map(id=>row([name(id),YF.students.find(x=>x.id===id).code,e.records[id].seat,e.room]))):empty('名单尚未导入','从名单入口选择本场学员。',link('W11','导入本场名单'))}</section><section class="panel"><h2>现场岗位</h2><dl class="kv"><dt>监考员</dt><dd>${staffName(e.staff.invigilator)}</dd><dt>录制员</dt><dd>${staffName(e.staff.recorder)}</dd><dt>设备</dt><dd>${e.room}-01</dd></dl><div class="actions">${link('W09',e.status==='draft'?'安排本场岗位':'查看岗位')}${link('W03','继续检查套卷')}</div>${actor.group==='academic'?notice('岗位授权由管理员安排。已开放场次的变更需要接手人确认。'):''}</section>`},
 W03(){return `${heading('完整题组与三科材料','仅完整题组进入本场随机池，学生一次抽取三科。',link('W01','返回准备'))}<section class="panel">${Object.entries(ExamSpec.papers).map(([id,paper])=>`<details class="prep-question"><summary>${id}号-v1 · 三科完整</summary>${subjects.map((n,q)=>`<h3>${n} · ${ExamSpec.time(ExamSpec.durations[q])}</h3><div class="paper">${esc(paper[q])}</div>`).join('')}</details>`).join('')}${e.status==='draft'?form('save-paper',check('complete','已核对17/19/21三份题组三科完整，确认选入本场'),'确认完整题组池'):notice('本场完整题组池已锁定；原抽题记录保持原版本。')}</section><section class="panel"><h2>18号 · 缺科样本</h2>${notice('缺少新闻播报，不进入随机池。','warning')}</section>`},
 W13(){return `${heading('本科评分分工','每位老师评其负责科目的全部学员。',link('U03','返回总览'))}<section class="panel">${form('save-assignments',table(['科目','老师1','老师2','应评学员'],subjects.map((n,q)=>row([n,...[0,1].map(t=>`<label><input type="checkbox" name="assignment-${q}" value="${t}" ${e.assignments[q].includes(t)?'checked':''} ${Object.keys(e.scores||{}).length?'disabled':''}> 本科全部</label>`),e.roster.length+'名']))),'保存评分分工')}${Object.keys(e.scores||{}).length?notice('已有评分，保持原分工。更正原分数请保留原因与处理记录。','warning'):''}</section><section class="panel"><h2>管理员分差提醒 · 演示配置</h2><p>当前：${e.scorePolicy?.differenceThreshold==null?'未配置，不限制分差':e.scorePolicy.differenceThreshold+'分（示例）'}。阈值由教研确认；提醒不会自动改分或限制老师独立评分。</p>${form('save-score-policy',field('threshold','示例分差阈值，留空表示未配置',e.scorePolicy?.differenceThreshold??'','number'),'保存演示提醒设置')}</section>`},
 W19(){return `${heading('账号与本场岗位','开场前安排工作人员，核对各人负责的现场岗位。',link('U03','返回总览'))}<section class="panel">${table(['工作人员','状态','本场岗位','操作'],Object.values(v.staff).map(s=>row([s.name,tag(s.active?'可用':'停用'),Object.entries(e.staff).filter(([,id])=>id===s.id).map(([role])=>role==='recorder'?'录制':'监考').join('、')||'暂无执行岗位',link('W09','查看岗位',{staff:s.id})])))}</section>`},
 W09(){const id=params.get('staff')||e.staff.recorder;return `${heading('岗位与未完任务',staffName(id)+' / '+e.name,link('W19','返回账号列表'))}<section class="panel">${e.status==='draft'?form('assign-staff',`<div class="form-grid">${select('monitor','监考员',Object.values(v.staff).filter(x=>x.active).map(x=>[x.id,x.name]),e.staff.invigilator)}${select('recorder','录制员',Object.values(v.staff).filter(x=>x.active).map(x=>[x.id,x.name]),e.staff.recorder)}</div>`,'保存本场岗位'):`<dl class="kv"><dt>监考员</dt><dd>${staffName(e.staff.invigilator)}</dd><dt>录制员</dt><dd>${staffName(e.staff.recorder)}</dd></dl>${notice('当前责任人已参与本场执行。确需临时换人时可查看候选方案，具体规则仍待确认。','warning')+link('T01','候选：临时更换工作人员')}`}<hr><p>所有开放场次的岗位或待接收任务全部移交后，才可停用账号。</p>${action('停用此账号','disable-staff',{staffId:id},'danger')}</section>`},
 T01(){const transfers=e.transfers||[],canCreate=actor.group==='admin'||staffAssigned();return `${heading('临时更换工作人员','低频候选场景 · 尚未确认是否需要。',link(actor.home,'返回岗位任务'))}${pendingRule('本页仅演示工作人员换班；不同于监考把学员交给录制员，正常考试无需经过此页')}${canCreate?`<section class="panel"><h2>发起本场移交</h2>${form('create-transfer',`<div class="form-grid">${select('role','移交岗位',actor.group==='admin'?[['invigilator','监考岗位'],['recorder','录制岗位']]:[[actor.group,actor.group==='recorder'?'录制岗位':'监考岗位']],actor.group==='admin'?'recorder':actor.group)}${select('to','接手人员',Object.values(v.staff).filter(x=>x.active).map(x=>[x.id,x.name]),'staff2')}</div>${reason()}${notice('录制移交沿用同一台设备。当前学员和待传原文件一并核对，不改变文件所属考试、学员和科目。')}`,'发出移交')}</section>`:''}<section class="panel"><h2>移交记录与待接收</h2>${transfers.length?transfers.slice().reverse().map(t=>`<div class="listrow"><div><h3>${t.role==='recorder'?'录制':'监考'} · ${staffName(t.from)} → ${staffName(t.to)}</h3><p>${t.id} · ${decisionStatus[t.status]||'待接收'}<br>${esc(t.reason)}</p></div>${link('T02','查看移交单',{id:t.id},'primary')}</div>`).join(''):empty('本场暂无移交','需要换人时发起，接手人在自己的任务列表接收。')}</section>`},
 T02(){const t=e.transfers.find(t=>t.id===params.get('id'));if(!t)return empty('移交单不可用','请从本人移交列表重新进入。',link('T01','返回移交列表'));const canReceive=t.to===actor.staffId&&t.role===actor.group&&t.status==='pending';return `${heading('工作人员更换 · '+t.id,'候选场景 · 本场岗位与原任务核对',link('T01','返回移交列表'))}<section class="panel">${tag(decisionStatus[t.status]||'待接收','warning')}<dl class="kv"><dt>岗位</dt><dd>${t.role==='recorder'?'录制':'监考'}</dd><dt>原负责人</dt><dd>${staffName(t.from)}</dd><dt>接手人</dt><dd>${staffName(t.to)}</dd><dt>当前学员</dt><dd>${t.person?name(t.person):'暂无场内学员'}</dd><dt>原设备</dt><dd>${e.room}-01</dd><dt>待传原文件</dt><dd>${t.files.length?t.files.map(esc).join('<br>'):'无待传原文件'}</dd><dt>移交原因</dt><dd>${esc(t.reason)}</dd></dl>${t.response?notice('接手处理说明：'+esc(t.response)):''}${canReceive?form('accept-transfer',`${reason('reason','接收或退回说明')}${check('verified','已核对当前学员、同一设备和上述原文件清单')}<div class="actions">${action('退回移交','reject-transfer',{id:t.id})}</div>`,'确认接收岗位与未完任务',{id:t.id}):''}${t.status==='pending'&&(actor.group==='admin'||t.from===actor.staffId)?button('撤回这份移交','cancel-transfer',{id:t.id}):''}${t.status==='accepted'?notice('接收完成。旧工作人员保留回执，接手人继续原任务；录制岗位需要复核设备。'):''}<div class="actions">${link(actor.home,'返回我的任务',{},'primary')}</div></section>`},
 M00(){return staffHome('invigilator')},
 M01(){if(!staffAssigned())return moved();return `${heading(e.room+' · 候考与交接','计划排次不随签到顺序变化。',link('M03','展示本考场签到码',{},'primary'))}${notice(e.current?'场内当前：'+name(e.current)+' · '+taskState(e.records[e.current]):'场内空闲，核对队首条件后可交接下一位。')}<section class="panel"><h2>本场队列</h2>${e.queue.map((id,i)=>{const rr=e.records[id];return `<div class="listrow"><div><h3>${name(id)} · 计划${rr.seat}</h3><p>当前队列${i+1} · ${taskState(rr)}</p></div>${link('M02','核对详情',{person:id})}</div>`}).join('')}</section><div class="actions">${link('M05','处理迟到、过号与缺考')}</div>`},
 M02(){if(!staffAssigned())return moved();if(!r)return empty('本场没有这名学员','返回本场名单选择。',link('M01','返回候考名单'));const next=e.queue.find(id=>!e.records[id].onsiteEnded&&e.records[id].attendance!=='absent');const can=!e.current&&next===p&&r.checkin&&r.draw&&!r.drawPending&&!r.onsiteEnded&&r.attendance!=='absent';return `${heading(name(p)+' · 核对详情',e.room+' / 计划排次'+r.seat,link('M01','返回候考名单'))}<section class="panel"><dl class="kv"><dt>机构编号</dt><dd>${YF.students.find(x=>x.id===p).code}</dd><dt>本人签到</dt><dd>${r.checkin?'已签到 · '+r.checkinAt:'等待本人签到'}</dd><dt>题套</dt><dd>${r.draw?r.draw+'号-v1'+(r.drawPending?' · 结果待查询':''):'等待本人抽取'}</dd><dt>现场状态</dt><dd>${taskState(r)}</dd></dl>${r.handoff!=='idle'?link('M04','查询本位交接',{person:p},'primary'):button('核对完成，交给场内','handoff',{person:p},'primary',!can)}${!can&&r.handoff==='idle'?notice(e.current?'场内仍有学员，等待本位结束。':next!==p?'请先处理队首学员；调整顺序请登记申请。':'签到或抽题确认尚未完成。','warning'):''}<div class="actions">${link('M05','登记本位现场例外',{person:p})}</div></section>${pendingRule('本人签到、手机整套抽题与15分钟备稿已明确；剩余现场细则待确认')}`},
 M03(){return `${heading(e.room+' · 到场签到','学生使用本人账号核对本场与考场。',link('M01','返回候考名单'))}<section class="panel"><div class="qr-placeholder" aria-label="二维码示意">▦</div><h2>${esc(e.name)}</h2><p>${e.date} · ${e.room}</p>${notice('图形为签到码示意，未连接真实扫码服务。可在评审外层切换学生身份，进入本人扫码页体验。')}<p>监考不能代学生签到。</p></section>`},
 M04(){const rr=r||e.records[e.current];if(rr?.handoff==='idle')return empty('尚未交接这位学员','请从候考名单核对学员条件后，交给场内录制员。',link('M02','核对这位学员',{person:rr.id},'primary')+link('M01','返回候考名单'));return `${heading('学员交接状态',rr?name(rr.id)+' / '+e.room:'暂无交接',link('M01','返回候考名单'))}${rr?`<section class="panel"><h2>${taskState(rr)}</h2><dl class="kv"><dt>学员</dt><dd>${name(rr.id)}</dd><dt>本场</dt><dd>${esc(e.name)}</dd><dt>接收岗位</dt><dd>${staffName(e.staff.recorder)}</dd></dl>${action('刷新原交接状态','refresh')}<hr>${rr.technicalSubmitted&&!rr.onsiteEnded?`<h3>录制员已提交三科技术检查</h3><p>作品朗读02:00 / 新闻播报01:00 / 话题评述02:00；音画与本地保存已检查。</p>${rr.technicalBlocked?notice('仍有视频问题待处理，不能放行。请联系录制员和负责人处理后刷新原状态。','warning'):form('release-person',check('verified','已核对本人三科技术检查结果，确认可以离场'),'确认技术核验并放行',{person:rr.id})}`:''}${rr.onsiteEnded?`${notice('本位现场结束，上传与评分继续留在原学员。可以回名单核对下一位。')}${link('M01','核对下一位学员',{},'primary')}`:notice('交接发出与场内接收分别记录，查询不会重发或替录制员接收。')}</section>`:empty('尚无当前交接','先从本场名单核对队首学员。',link('M01','返回候考名单'))}`},
 M05(){if(!staffAssigned())return moved();return `${heading('现场例外申请','保留计划排次与原状态，由负责人记录决定。',link('M01','返回候考名单'))}<section class="panel">${form('create-exception',`<div class="form-grid">${select('person','本场学员',e.roster.map(id=>[id,name(id)]),p)}${select('type','申请事项',[['reorder','过号 / 调整到队尾'],['absence','登记缺考'],['return','恢复候考'],['redraw','重新抽题']],'reorder')}</div>${reason()}${pendingRule('缺考、过号、恢复候考和重抽由管理员演示处理，不自动缩小评分名单')}`,'提交现场申请')}</section>${link('X01','查看申请与处理结果')}`},
 A00(){return staffHome('recorder')},
 A01(){if(!staffAssigned())return moved();return `${heading('设备与当前人',e.room+' / '+e.room+'-01',link('A00','返回录制任务'))}<section class="panel"><h2>开场或接手后复核设备</h2>${form('check-device',check('camera','画面方向和取景已核对')+check('audio','声音可辨，收音已核对')+check('mirror','手机与大屏同画面已核对'),'记录设备检查')}${e.deviceChecked?notice('本场设备检查已记录。'):''}<div class="actions">${link('A04','核对当前学员',{},'primary')}</div></section>`},
 A04(){if(!staffAssigned())return moved();const active=e.current,rr=active?e.records[active]:r;return `${heading(active?name(active)+' · 本位任务':rr?.onsiteEnded?name(rr.id)+' · 本位完成':'等待下一位交接',e.name+' / '+e.room)}${active?`<section class="panel"><h2>${taskState(rr)}</h2><dl class="kv"><dt>学员</dt><dd>${name(active)}</dd><dt>题套</dt><dd>${rr.draw?rr.draw+'号-v1':'尚无题套'}</dd><dt>设备检查</dt><dd>${e.deviceChecked?'已记录':'待复核'}</dd></dl><div class="actions">${rr.technicalSubmitted?notice('技术检查已提交，等待监考确认放行；当前考位尚未释放。'):r.handoff==='pending'?button('确认当前学员并接收','accept-person',{person:active},'primary',!e.deviceChecked):link('A02','继续当前科目',{person:active,q:rr.subject},'primary')}${link('A01','复核设备')}</div></section>`:empty(rr?.onsiteEnded?'本位已结束，等待下一位':'等待监考交接学员',rr?.onsiteEnded?'上一位的原文件仍留在原考试、原学员下，可以继续上传。':'监考发出学员交接后，在这里核对并接收。',link('A03','处理原文件队列',{},'primary'))}${rr?`<section class="panel"><h2>${name(rr.id)} · 三科进度</h2>${subjects.map((n,i)=>`<div class="listrow"><div><h3>${n}</h3><p>${uploadState(rr.files[i])}</p></div>${rr.files[i]?link('A05','原文件详情',{person:rr.id,q:i,file:rr.files[i].id}):tag('待录制')}</div>`).join('')}</section>`:''}<div class="actions">${link('X01','异常处置与回执')}${link('A03','本机原文件')}</div>`},
 A02(){if(!staffAssigned())return moved();if(!r||e.current!==p||r.handoff!=='accepted')return empty('请先接收本场当前学员','保持学员、题套和设备一致后再录制。',link('A04','核对当前学员'));if(r.technicalSubmitted)return empty('技术检查已提交','请等待监考确认放行，当前人不能再次开始录制。',link('A04','查看本位状态'));const sq=r.subject,f=r.files[sq],duration=ExamSpec.durations[sq];let content='';
 if(r.stage==='recording')content=`<div class="record-question"><div class="question-number">${sq+1} / 3 · ${r.draw||17}号-v1</div><h1>${subjects[sq]}</h1><div class="paper">${question(sq)}</div></div><section class="panel">${tag('正在录制','error')}<div class="timer" id="timer" data-start="${r.started}" data-duration="${duration}">${ExamSpec.time(duration)}</div><p>本科到时自动结束并保存；保存结果确认前不能进入下一科。</p><div class="actions">${action('异常结束','interrupt',{person:p,q:sq},'danger')}${action('提前结束本科并保存','finish',{person:p,q:sq},'primary')}</div></section>`;
 else if(r.stage==='saving')content=empty('正在保存本科原文件','重新进入后可查询原保存任务。',button('查询本机保存结果','query-save',{person:p,q:sq},'primary'));
 else if(f?.abnormal)content=empty('异常片段已保留','原文件已进入异常单，不得直接覆盖或放行。',link('X01','查看异常进展',{person:p},'primary'));
 else if(f)content=`<section class="panel"><h2>本科本地已保存 · 技术检查</h2>${video(name(p)+' / '+subjects[sq]+' / v'+f.version,duration)}<dl class="kv"><dt>原文件</dt><dd>${f.id}</dd><dt>本科时限</dt><dd>${ExamSpec.time(duration)}</dd><dt>状态</dt><dd>${uploadState(f)}</dd></dl>${!f.localReviewed?form('verify-local',check('picture','已检查画面清晰、人物与科目正确')+check('sound','已检查声音可辨，无静音或明显中断')+check('completeVideo','已核对时长与完整性，本地保存成功'),'确认本科技术检查并加入上传',{person:p,q:sq}):notice('本科技术检查已确认。上传与考后材料核验另行记录。')}<div class="actions">${r.files.every(Boolean)?link('A06','核对三科并提交离场前检查',{person:p},'primary'):button('进入下一科','next-subject',{person:p},'primary',!f.localReviewed)}${link('A03','查看上传队列')}${link('X02','报告视频问题',{person:p,q:sq,new:'1'})}</div></section>`;
 else content=`<div class="two-col"><section class="panel"><h2>${subjects[sq]} · 本科准备</h2><div class="paper">${question(sq)}</div><p>${r.draw||17}号-v1 · ${e.name}</p></section><section class="panel">${video('准备画面示意',duration)}<p>${name(p)} · 本科${ExamSpec.time(duration)}，到时自动停止</p>${button('开始本科录制','start-record',{person:p,q:sq},'primary',!e.deviceChecked)}</section></div>`;
 return `${heading(name(p)+' · '+subjects[sq],e.room+' / 限时'+ExamSpec.time(duration)+' · 自动结束保存',link('A04','查看本位任务',{person:p}))}${content}`},
 A06(){if(!staffAssigned())return moved();if(!r||e.current!==p||r.handoff!=='accepted')return empty('没有当前学员待核验','请先核对本位任务。',link('A04','返回当前学员'));const ready=r.files.every(f=>f?.local&&f.localReviewed&&!f.abnormal);return `${heading('三科离场前技术检查',name(p)+' / '+e.room,link('A04','返回本位任务'))}<section class="panel">${notice('录制员提交技术检查，监考核对后确认放行。上传后教务仍要核验评分材料。')}<div class="technical-list">${subjects.map((n,q)=>{const f=r.files[q];return `<div class="listrow"><div><h3>${n} · 时限${ExamSpec.time(ExamSpec.durations[q])}</h3><p>${f?.localReviewed?'✓ 画面、声音、时长与本地保存已确认':'尚未完成本科技术检查'}</p><small>${f?.id||'缺少本地文件'}</small></div>${f?link('A05','查看本科原文件',{person:p,q,file:f.id}):link('A02','继续录制',{person:p})}</div>`}).join('')}</div>${!ready?notice('三科检查未齐备，不能提交技术核验或放行。','warning'):r.technicalSubmitted?notice('技术检查已提交，等待监考确认放行。'):form('end-person',check('verified','已逐科核对本人的音画、时长与保存结果，提交给监考确认'),'提交技术检查，等待监考放行',{person:p})}${link('X02','登记本位视频问题',{person:p,q:r.subject,new:'1'})}</section>`},
 A03(){const files=Object.values(e.records).flatMap(rr=>[...rr.files,...rr.history.flat()].filter(Boolean)).filter(f=>f.custodian===actor.staffId);return `${heading('本机原文件与上传','切换学员不改变文件所属考试、学员、科目和版本。',link('A04','查看当前学员'))}<section class="panel">${files.length?files.map(f=>`<div class="listrow"><div><h3>${name(f.person)} · ${subjects[f.q]} · v${f.version}</h3><p>${esc(e.name)} / ${f.id}<br>${uploadState(f)}</p></div>${link('A05','查看原文件',{person:f.person,q:f.q,file:f.id})}</div>`).join(''):empty('当前没有本人保管的原文件','完成本位保存或确认接收移交后，文件会出现在本场队列。',link('A04','查看当前学员'))}</section>`},
 A05(){const f=Object.values(e.records).flatMap(rr=>[...rr.files,...rr.history.flat()]).find(f=>f?.id===params.get('file'))||r?.files[q];if(!f||f.custodian!==actor.staffId)return empty('当前没有这份原文件的保管任务','请从本人队列进入，或查询岗位移交回执。',link('A03','返回本机队列')+link('T01','查看移交'));return `${heading(name(f.person)+' · '+subjects[f.q],e.name+' / 原文件v'+f.version,link('A03','返回原文件队列'))}<section class="panel">${video(f.id)}<dl class="kv"><dt>所属场次</dt><dd>${esc(e.name)}</dd><dt>原学员</dt><dd>${name(f.person)}</dd><dt>原录制人员</dt><dd>${staffName(f.originRecorder)}</dd><dt>当前保管人</dt><dd>${staffName(f.custodian)}</dd><dt>设备</dt><dd>${f.device}</dd><dt>上传结果</dt><dd>${uploadState(f)}</dd></dl>${f.abnormal?notice('异常原片段保持留存，不能作为完整评分材料。请查看处置回执。','warning'):''}<div class="actions">${f.upload==='uploading'?button('查询原文件上传结果','query-upload',{fileId:f.id},'primary'):action(f.upload==='received'?'后台已收到':'上传 / 重试原文件','upload',{fileId:f.id},'primary',f.abnormal||!f.localReviewed||f.upload==='received')}${!f.localReviewed?notice('本科尚未完成本地技术检查，请返回本科录制页核对后再上传。','warning')+link('A02','返回本科技术检查',{person:f.person,q:f.q},'primary'):''}${link('X01','查看异常回执',{person:f.person})}</div></section>`},
 W04(){return `${heading('本场材料核对','按完整名单检查原视频；补录后重新核验版本。',link('X01','处理材料问题'))}<div class="tabs">${subjects.map((n,i)=>link('W04',n,{q:i},q===i?'active':'')).join('')}</div><section class="panel"><h2>${subjects[q]} · ${e.roster.length}名应考学员</h2>${table(['学员','当前视频','状态','核对'],e.roster.map(id=>{const rr=e.records[id],f=rr.files[q];return row([name(id),f?'v'+f.version:'缺视频',uploadState(f),link('W14','查看材料',{person:id,q})])}))}<div class="actions">${button(e.opened[q]?'重新检查本科开放条件':'核对后开放本科评卷','open-subject',{q},'primary')}</div>${e.opened[q]?notice('本科已开放。后续替换或补录将关闭本科开放，受影响评分需要重评。'):''}</section>`},
 W14(){if(!r)return empty('本场没有此学员材料','返回清单选择。',link('W04','返回清单',{q}));const f=r.files[q];return `${heading(name(p)+' · '+subjects[q],e.name+' / 材料版本核对',link('W04','返回本科材料清单',{q}))}<section class="panel">${f?`${video(f.id)}<dl class="kv"><dt>来源设备</dt><dd>${f.device}</dd><dt>有效候选版本</dt><dd>v${f.version}</dd><dt>当前状态</dt><dd>${uploadState(f)}</dd></dl>${!r.onsiteEnded?notice('等待监考核验放行后，再进行考后评分材料核验。','warning'):''}${button(f.checked?'本版材料已核验':'核验本版评分材料','confirm-material',{person:p,q},'primary',!r.onsiteEnded||!r.technicalSubmitted||f.checked||f.upload!=='received'||f.abnormal)}`:notice('后台尚无本人的本科视频，请联系本场录制负责人核对原文件。','warning')}<div class="actions">${link('X02','登记材料问题',{person:p,q,new:'1'})}${link('X01','查看原异常单',{person:p})}</div></section><section class="panel"><h2>原版本留存</h2>${r.history[q].length?r.history[q].map(f=>`<p>${f.id} · ${f.abnormal?'异常片段':'旧版视频'} · 原归属保留</p>`).join(''):'暂无旧版本'}</section>`},
 W05(){const assigned=e.assignedSubjects||[];return `${heading('我的评卷任务',actor.name+' · 本人负责科目，评本科全部学员',link('U02','切换考试'))}${assigned.length?`<div class="three-col">${assigned.map(q=>{const count=e.roster.filter(p=>e.scores[scoreKey(q,p)]).length;return `<section class="taskcard">${tag(e.opened[q]?'已开放评卷':'材料待开放')}<h2>${subjects[q]}</h2><p>本人已保存 ${count}/${e.roster.length}</p>${link('W16','进入本科队列',{q},'primary')}</section>`}).join('')}</div>`:empty('暂无本人分配的科目','请联系管理员确认本场评分分工。')}<section class="panel"><div class="actions">${link('X01','本人视频问题')}${link('W24','本人改分申请与回执')}</div></section>`},
 W16(){if(!e.assignedSubjects?.includes(q))return empty('当前科目未分配给本人','从本人任务选择负责科目。',link('W05','返回本人任务'));const filter=params.get('filter')||'all',list=e.roster.filter(id=>{const k=scoreKey(q,id);return filter==='all'||filter==='ungraded'&&!e.scores[k]||filter==='saved'&&!!e.scores[k]||filter==='draft'&&e.drafts[k]!==undefined||filter==='issue'&&e.blockedFiles.includes(`${id}-${q}`)});return `${heading(subjects[q]+' · 本科队列','仅本人评分与草稿；不会显示其他老师原始分。',link('W05','返回本人科目'))}<div class="tabs">${[['all','全部'],['ungraded','待评'],['draft','草稿'],['saved','已保存'],['issue','视频问题']].map(([f,l])=>link('W16',l,{q,filter:f},filter===f?'active':'')).join('')}</div><section class="panel">${list.length?table(['本人任务','本人分数','状态','操作'],list.map(id=>{const k=scoreKey(q,id),s=e.scores[k];return row([name(id),s?.value??'未保存',e.blockedFiles.includes(`${id}-${q}`)?tag('材料问题待处理','warning'):e.drafts[k]!==undefined?tag('有未提交输入','warning'):tag(s?'已保存':'待评'),link('W06',s?'查看本人评分':'进入评分',{person:id,q},'primary')])})):empty('当前筛选没有任务','可切回全部任务继续。',link('W16','显示全部',{q}))}<div class="actions">${link('W17','查看本科完成情况',{q})}</div></section>`},
 W06(){if(!r||!e.assignedSubjects?.includes(q))return empty('没有本人的这份评分任务','从本人队列进入。',link('W05','返回本人任务'));const k=scoreKey(q,p),saved=e.scores[k],f=r.files[q],blocked=!e.opened[q]||!f?.checked||e.blockedFiles.includes(`${p}-${q}`),value=e.drafts[k]??saved?.value??'';return `${heading(subjects[q]+' · '+name(p),'当前材料 '+(f?'v'+f.version:'尚未就绪'),link('W16','返回本科队列',{q})+link('W17','本科完成记录',{q}))}${blocked?notice('材料尚未开放或存在待处理问题。保留原任务，暂不能提交评分。','warning'):''}<div class="two-col"><div><section class="panel">${video('评分用视频 '+(f?'v'+f.version:''))}<div class="actions">${link('X02','报告原视频问题',{person:p,q,new:'1'})}</div></section><section class="panel"><h2>本次试题</h2><div class="paper">${question(q)}</div></section></div><section class="panel score-form">${rubric(q)}<h2>${saved?'本人已保存评分':'本科评分'}</h2>${saved?`<p class="cell-number">${saved.value}分</p><p class="small muted">绑定视频v${saved.videoVersion} · 原评分修订${saved.revision}</p>${notice('已有评分保留原记录。改分需说明原因并查看处理回执；演示由管理员处理，正式决定权待确认。')}`:''}<label for="score">${saved?'拟更正分数':'分数'} / 100</label><input id="score" class="score-input" type="number" min="0" max="100" step="0.01" value="${esc(value)}" data-score-person="${p}" data-score-q="${q}" ${blocked||saving?'disabled':''}><p class="field-hint">0–100，最多两位小数（演示假设）</p><p id="score-band-hint" class="field-hint" aria-live="polite">保存后计入本人评分分布；其他评委分数不展示。</p><div class="save-status" id="score-status">${e.drafts[k]!==undefined?'有本机保留的未提交输入':saved?'已保存原分数':'尚未保存评分'}</div>${saved?`${reason('correction-reason','改分原因')}<div class="actions">${action('提交改分申请','correction',{person:p,q},'primary',blocked||saving)}</div>${link('W24','查看本人申请')}`:`<div class="actions">${action(saving?'正在保存…':'只保存','save-score',{person:p,q},'',blocked||saving)}${action('保存并下一份','save-next',{person:p,q},'primary',blocked||saving)}</div>`}</section></div>${ownBands(q)}`},
 W17(){if(!e.assignedSubjects?.includes(q))return empty('本科尚未分配','返回本人任务。',link('W05','本人任务'));const count=e.roster.filter(id=>e.scores[scoreKey(q,id)]).length,unsaved=e.roster.filter(id=>e.drafts[scoreKey(q,id)]!==undefined).length;return `${heading(subjects[q]+' · 本人完成记录','已保存与仍需处理的事项分别显示。',link('W05','选择其他科目'))}<section class="panel"><h2>${count===e.roster.length&&e.roster.length?'本科全部评分已保存':'本科仍有未评任务'}</h2><p>已保存 ${count}/${e.roster.length}；未提交输入 ${unsaved} 份。</p><div class="actions">${link('W16','继续本人队列',{q},'primary')}${link('X01','查看本人问题')}${link('W24','查看改分回执')}</div></section>`},
 W10(){return `${heading('全场评卷概览','管理员查看全场，原始分按老师独立保存。',link('W07','核对本场成绩',{},'primary'))}${subjects.map((n,q)=>`<section class="panel"><h2>${n}</h2>${table(['学员',...e.assignments[q].map(t=>'老师'+(t+1)), '本科均分','评委分差'],e.roster.map(id=>row([name(id),...e.assignments[q].map(t=>e.scores[`${q}-${t}-${id}`]?.value??'缺评'),YF.mean(examId,q,id)??'缺评未合分',spread(q,id)])))}</section>`).join('')}`},
 W07(){const issues=YF.publishIssues(examId);return `${heading('成绩核对与发布','缺评不缩小分母，导出与发布分别操作。',link('W18','查看发布记录'))}<section class="panel">${issues.length?notice('尚不能发布：'+issues.slice(0,6).map(esc).join('；')+(issues.length>6?'等'+issues.length+'项':''),'warning'):notice('本场各科材料和全部分配老师评分齐备，可进入发布预览。')}${table(['学员',...subjects,ExamSpec.totalLabel],e.roster.map(id=>row([name(id),...subjects.map((_,q)=>YF.mean(examId,q,id)??'缺评未合分'),totalFor(id)??'缺评不计算'])))}<div class="actions">${link('W08','查看发布预览',{},'primary')}${action('导出核对表','export')}${link('W10','定位缺评')}${link('W24','查看改分申请')}</div></section>${totalBanner()}`},
 W08(){const issues=YF.publishIssues(examId),last=e.publications.at(-1),unchanged=last?.scoreRev===e.scoreRev;return `${heading('发布预览','确认后生成独立快照，学生只看到自己的结果。',link('W07','返回核对'))}<section class="panel">${table(['学员',...subjects,ExamSpec.totalLabel],e.roster.map(id=>row([name(id),...subjects.map((_,q)=>YF.mean(examId,q,id)??'尚不具备结果'),totalFor(id)??'缺评不计算'])))}${totalBanner()}${issues.length?notice('仍有'+issues.length+'项缺评或材料/改分待办，先处理后发布。','warning'):unchanged?notice('当前结果已发布，重复提交不会新增版本。'):notice(last?'评分已有更正。学生目前仍看v'+last.version+'；确认后发布新版本。':'本场尚未发布。')}<div class="actions">${action(unchanged?'已发布本版本':last?'发布更正版本':'发布本次结果','publish',{scoreRev:e.scoreRev},'primary',!!issues.length||unchanged)}</div></section>`},
 W18(){return `${heading('成绩发布记录','保留实际发布快照；后续评分不会覆盖旧版。',link('W07','回本场核对'))}${e.publications.length?e.publications.slice().reverse().map(s=>`<section class="panel"><h2>发布v${s.version}</h2><p>${s.publishedAt} · ${esc(s.name)}</p>${table(['学员',...subjects,ExamSpec.totalLabel],e.roster.map(id=>row([name(id),...(s.results[id]||[]),ExamSpec.total(s.results[id])??'缺评不计算'])))}${totalBanner()}</section>`).join(''):empty('本场尚无发布记录','评分齐备后从核对页发布。',link('W07','核对条件'))}`},
 W24(){const list=e.corrections||[];return `${heading(actor.group==='teacher'?'我的改分申请':'改分申请与处理','申请、原分数、原因和处理结果一起保留。',link(actor.group==='teacher'?'W05':'W07','返回本场任务'))}${pendingRule('已有分数变更由老师提出、管理员处理；正式审批角色和条件待CF07确认')}<section class="panel">${list.length?list.slice().reverse().map(c=>`<div class="listrow"><div><h3>${name(c.person)} · ${subjects[c.q]}</h3><p>老师${c.teacher+1}：${c.oldValue} → ${c.newValue} · ${decisionStatus[c.status]}<br>${esc(c.reason)}</p></div>${link('W25','查看申请',{id:c.id},'primary')}</div>`).join(''):empty('当前没有改分申请','老师从本人已评分任务填写新分数与原因后提交。')}</section>${link('W26','查看原分数审计记录')}`},
 W25(){const c=e.corrections?.find(c=>c.id===params.get('id'));if(!c)return empty('当前没有这份申请','请从本人的申请列表进入。',link('W24','返回申请列表'));return `${heading('改分申请 · '+c.id,name(c.person)+' / '+subjects[c.q],link('W24','返回申请列表'))}<section class="panel">${tag(decisionStatus[c.status],'warning')}<dl class="kv"><dt>申请老师</dt><dd>评卷老师${c.teacher+1}</dd><dt>原分数</dt><dd>${c.oldValue}</dd><dt>申请分数</dt><dd>${c.newValue}</dd><dt>绑定视频</dt><dd>v${c.videoVersion}</dd><dt>申请原因</dt><dd>${esc(c.reason)}</dd></dl>${c.response?notice('处理结果：'+esc(c.response)):''}${actor.group==='admin'&&c.status==='pending'?form('decide-correction',`${reason()}${select('decision','处理方式',[['approve','同意申请分数'],['reject','退回申请']],'approve')}${pendingRule('本演示由管理员处理改分申请',true)}`,'确认处理',{id:c.id}):''}${actor.group==='teacher'&&c.status==='pending'?button('撤回本人申请','cancel-correction',{id:c.id}):''}<div class="actions">${link('W06','返回原评分任务',{person:c.person,q:c.q})}${link('W07','核对更正后结果')}</div></section>`},
 W26(){return `${heading('分数变更记录','保留改分或材料替换前的原始评分。',link('W24','返回改分申请'))}<section class="panel">${e.scoreAudit.length?table(['原任务','原分数','视频版本','原因','记录时间'],e.scoreAudit.slice().reverse().map(x=>row([subjects[Number(x.key.split('-')[0])]+' · '+name(x.key.split('-')[2])+' · 老师'+(Number(x.key.split('-')[1])+1),x.value,'v'+x.videoVersion,esc(x.reason),x.at]))):empty('暂时没有分数变更记录','获处理的改分或材料替换会保留原始分记录。')}</section>`},
 X01(){const list=(e.exceptions||[]).filter(x=>!params.get('person')||x.person===params.get('person'));return `${heading(actor.group==='teacher'?'本人视频问题':'异常待办与处理回执','每份异常保留原场次、学员、科目和处理过程。',link(actor.home,'返回我的任务'))}<section class="panel">${list.length?list.slice().reverse().map(x=>`<div class="listrow"><div><h3>${name(x.person)} · ${exceptionType[x.type]}</h3><p>${x.id} · ${decisionStatus[x.status]}<br>${esc(x.reason)}</p></div>${link('X02','查看原单',{id:x.id,person:x.person,q:x.q},'primary')}</div>`).join(''):empty('当前没有待查异常','出现视频问题或现场例外时，在原任务中登记。')}</section>${['admin','academic'].includes(actor.group)?link('W04','回材料清单继续核对'):''}`},
 W15(){return this.X01()},
 X02(){const x=e.exceptions.find(x=>x.id===params.get('id'));if(!x&&params.get('new')==='1'&&r){const types=actor.group==='teacher'?[['material','报告视频问题']]:actor.group==='recorder'?[['material','原视频核验'],['retake','申请补录']]:[['material','原视频核验'],['retake','申请补录'],['replace','替换有效视频']];return `${heading('登记原任务异常',name(p)+' / '+subjects[q],link(actor.group==='teacher'?'W06':actor.group==='recorder'?'A04':'W14','返回原任务',{person:p,q}))}<section class="panel">${form('create-exception',`${select('type','异常类型',types,types[0][0])}${reason()}${notice('登记不会给0分或删除任务；处置完成后回原任务继续。')}`,'提交异常',{person:p,q})}</section>`;}if(!x)return empty('没有这份异常单','返回本人任务列表查看。',link('X01','异常列表'));const rr=e.records[x.person],options=[['reject','退回申请，说明原因']];if(x.type==='material')options.unshift(['original-ok','原视频核验可用'],['approve','同意补录并重新核验']);else options.unshift(['approve',['retake','replace'].includes(x.type)?'同意补录并重新核验':'同意本次现场调整']);return `${heading('异常单 · '+x.id,name(x.person)+' / '+exceptionType[x.type],link('X01','返回异常列表'))}<section class="panel">${tag(decisionStatus[x.status],'warning')}<dl class="kv"><dt>原场次</dt><dd>${esc(e.name)}</dd><dt>学员</dt><dd>${name(x.person)}</dd><dt>涉及范围</dt><dd>${['material','retake','replace'].includes(x.type)?subjects[x.q]:'本场候考与入场安排'}</dd><dt>原文件</dt><dd>${x.fileId||'现场安排事项'}</dd><dt>原因</dt><dd>${esc(x.reason)}</dd></dl>${x.response?notice('处理说明：'+esc(x.response)):''}${actor.group==='admin'&&x.status==='pending'?form('decide-exception',`${select('decision','处理方式',options,options[0][0])}${reason('reason','决定与后续责任说明')}${check('verified','选择原视频可用时，已核验原文件画面与声音')}${pendingRule(['material','retake','replace'].includes(x.type)?'本演示由管理员处理视频例外；补录沿用原题套，旧片段保留，受影响分数重新评阅':'本演示由管理员处理现场特殊情况；不自动计算缺考分或减少应评人数',true)}`,'记录决定并交给下一岗位',{id:x.id}):''}${x.status==='executing'?notice('已产生原学员本科的重新录制任务。录制员接收后开始；旧片段已保留，受影响评分已转为待重评。'):''}${x.status==='awaiting_material'?notice('本位录制已结束，等待原文件上传和材料复核。'):''}${x.type==='absence'&&x.status==='resolved'?notice('缺考记录已生效；不自动缩减应评人数或计算缺考分数。成绩规则仍待确认，可由监考提交恢复候考申请。','warning'):''}<div class="actions">${link('A04','查看当前录制任务',{person:x.person})}${link('W14','核对本位新材料',{person:x.person,q:x.q})}${link('W06','回本人原评分任务',{person:x.person,q:x.q})}${link('M01','查看本场候考')}</div></section>`},
 S00(){return `${heading('我的考试','每场安排和成绩分别保留。')}<div>${v.exams.map(x=>`<section class="panel"><h2>${esc(x.name)}</h2><p>${x.date} · ${x.room} · ${status(x)}</p><div class="actions">${link('S01','查看本场安排',{exam:x.id},'primary')}${link('S02',x.publicationVersion?'查看本人成绩':'查看发布状态',{exam:x.id})}</div></section>`).join('')}</div>${!v.exams.length?empty('暂无本人的考试安排','待教务核对并导入本场名单后即可查看。'):''}`},
 S01(){return `${heading('本场安排',e.name,link('S00','返回我的考试'))}<section class="panel"><dl class="kv"><dt>本人</dt><dd>${actor.name}</dd><dt>日期</dt><dd>${e.date}</dd><dt>考场</dt><dd>${e.room}</dd><dt>计划排次</dt><dd>${r.seat}</dd><dt>当前状态</dt><dd>${taskState(r)}</dd></dl><div class="actions">${link(r.checkin?'S04':'S03',r.checkin?'查看签到结果':'扫一扫签到',{},'primary')}${link('D01','本次抽题记录')}${link('S06','本人参加进度')}</div></section>${pendingRule('签到、抽题、候考的具体先后及放行规则待CF01/02确认')}`},
 S03(){const scan=params.get('scan');if(scan==='wrong'||scan==='expired')return empty(scan==='wrong'?'这不是本人本场考场':'签到码已失效','未写入任何签到记录，请重新核对本场签到码。',link('S03','重新扫码',{},'primary'));return `${heading('本人扫码签到','确认考试、考场和本人信息。',link('S01','返回本场安排'))}<section class="panel">${scan!=='valid'?`<div class="scan-window"><strong>扫码画面示意</strong></div><p class="fine">此为虚构交互演示，未接真实相机。</p><div class="actions">${link('S03','模拟扫描本场有效码',{scan:'valid'},'primary')}${link('S03','体验扫错场次',{scan:'wrong'})}${link('S03','体验失效码',{scan:'expired'})}</div>`:`<dl class="kv"><dt>考试</dt><dd>${esc(e.name)}</dd><dt>考场</dt><dd>${e.room}</dd><dt>本人</dt><dd>${actor.name}</dd><dt>机构编号</dt><dd>${YF.students.find(x=>x.id===actor.studentId).code}</dd></dl>${r.checkin?link('S04','查看原签到结果',{},'primary'):button('确认本人信息并签到','checkin',{person:actor.studentId,scan:'valid'},'primary',e.status==='draft')}`}</section>`},
 S04(){return `${heading('本人签到结果',e.name)}<section class="panel"><h2>${r.checkin?'本人签到已确认':'本人尚未签到'}</h2><p>${actor.name} / ${e.room}</p><p>${r.checkin?r.checkinAt:'请到本人安排考场扫码'}</p>${notice('签到成功不等于可以自行进入场内，请按工作人员引导候考。')}<div class="actions">${link(r.checkin?'S01':'S03',r.checkin?'查看候考安排':'前往扫码',{},'primary')}${link('D01','查看本次抽题')}</div></section>`},
 D01(){return `${heading('三科整套抽题与备稿',e.name+' / '+actor.name,link('S06','查看本人进度'))}<section class="panel"><h2>${r.draw?'本次题组：'+r.draw+'号-v1':'一次抽取三科试题'}</h2>${r.drawPending?notice('本次抽题已生成，请查询原结果；倒计时按原起点继续，不重复抽题。','warning'):r.draw?notice('三科题目已一次锁定。重复点击、返回与刷新保持原题组。'):notice('本人签到后，在手机上一键抽取完整三科题组。')}<div class="actions">${r.draw?button('查询本次抽题结果','query-draw',{person:p},'primary'):button('一次抽取三科题目','draw',{person:p},'primary',!r.checkin||r.onsiteEnded)}</div></section>${r.draw&&!r.drawPending?prepPanel(r)+`<section class="panel"><h2>本次三科题目</h2>${subjects.map((n,q)=>`<details class="prep-question" ${q===0?'open':''}><summary>${n} · 录制${ExamSpec.time(ExamSpec.durations[q])}</summary><div class="paper">${esc(ExamSpec.paper(r.draw)[q])}</div></details>`).join('')}<p class="fine">不能自行重抽；遇到错题或异常请联系监考，从原记录按异常规则处理。</p></section>`:''}`},
 S06(){return `${heading('本人参加进度',e.name,link('S01','返回本场安排'))}${r.draw&&!r.drawPending&&!r.onsiteEnded?prepPanel(r):''}${studentProgress(r,e)}`},
 S05(){return `${heading('我的历次成绩','按本人实际参加场次读取已发布记录。')}${v.exams.map(x=>`<section class="panel"><h2>${esc(x.name)}</h2><p>${x.date} · ${x.publicationVersion?'已发布v'+x.publicationVersion:'待发布'}</p>${link('S02',x.publicationVersion?'查看本人成绩':'查看发布状态',{exam:x.id},'primary')}</section>`).join('')}`},
 S02(){const requested=params.get('version'),pub=requested?e.publications.find(x=>String(x.version)===requested):e.publications.at(-1);if(requested&&!pub)return empty('没有这份发布版本','请核对原发布记录；不会用另一版本替代当前请求。',link('S02','查看最新已发布版本',{},'primary'));return `${heading('本人成绩',e.name,link('S05','返回历次成绩'))}${pub?`<section class="panel"><h2>${actor.name} · 发布v${pub.version}</h2><p>${pub.publishedAt}</p><div class="score-grid">${subjects.map((n,q)=>`<div><span>${n}</span><strong>${pub.result[q]}</strong></div>`).join('')}</div><div class="reference-total"><span>${ExamSpec.totalLabel}</span><strong>${ExamSpec.total(pub.result)??'待齐备'}</strong></div>${totalBanner()}${notice('当前显示本人的实际发布快照。没有同学成绩或老师原始分。')}<div class="actions">${e.publications.map(x=>link('S02','查看v'+x.version,{version:x.version})).join('')}</div></section>`:empty('本场成绩尚未发布','机构核对发布后在这里查看本人结果。',action('刷新发布状态','refresh'))}`}
 };}
function question(q){return ExamSpec.paper(exam()?.records?.[personId()]?.draw||17)[q];}
function moved(){return empty('本场岗位已移交或尚未分配','请查看移交回执，或回本人任务选择仍负责的场次。',link('T01','查看移交记录')+link('U02','查看本人考试'));}
function staffHome(role){const v=context();return `${heading('我的'+(role==='recorder'?'录制':'监考')+'任务',actor.name+' · 按场次接续工作',link('U02','考试列表'))}${v.exams.filter(x=>x.status!=='archived').map(x=>{const ev=YF.view(actorId,x.id).exam,assigned=ev?.staff?.[role]===actor.staffId,pending=(ev?.transfers||[]).filter(t=>t.to===actor.staffId&&t.role===role&&t.status==='pending');return `<section class="panel"><h2>${esc(x.name)}</h2><p>${x.date} · ${x.room} · ${status(x)}</p>${assigned?notice('当前由本人负责本场'+(role==='recorder'?'录制':'监考')+'岗位。'):notice('本场有移交记录。接收完成后获得执行任务。','warning')}<div class="actions">${assigned&&x.status!=='draft'?link(role==='recorder'?(ev.deviceChecked?'A04':'A01'):'M01','进入本人岗位',{exam:x.id},'primary'):''}${(ev?.transfers||[]).length?link('T01','工作人员更换记录',{exam:x.id}):''}${pending.map(t=>link('T02','接收 '+t.id,{exam:x.id,id:t.id},'primary')).join('')}</div></section>`}).join('')||empty('当前暂无本人的岗位任务','管理员分配或原人员发起移交后，可从这里接续。')}`;}
function render(){const v=context();renderedState=JSON.stringify(v);const allowed=RolePolicy.canOpen(actorId,screen),global=['U01','U02','U04','S00','S05','M00','A00'].includes(screen);if(!allowed){root.innerHTML=shell(empty('当前账号无此页面权限','请回到本人任务。',link(actor.home,'回到我的任务')));return;}if(!v.exam&&!global){root.innerHTML=shell(empty('没有这场考试的本人任务','请从本人列表选择有效场次。',link(actor.home,'返回本人任务')));return;}if(v.faults.permission&&!global){root.innerHTML=shell(empty('当前任务授权待核对','请联系本场管理员核对负责范围。',link(actor.home,'返回本人任务')));return;}const map=pages();root.innerHTML=shell(map[screen]?map[screen]():empty('页面不存在','请返回本人任务。',link(actor.home,'本人任务')));if(v.exam?.status==='archived')root.querySelectorAll('form input,form select,form textarea,form button,[data-command],[data-ui=correction],[data-ui=save-score],[data-ui=save-next],[data-ui=publish]').forEach(el=>el.disabled=true);if(screen==='W13'&&Object.keys(v.exam?.scores||{}).length)root.querySelector('form button[type=submit]')?.setAttribute('disabled','');document.title='艺风 · '+actor.label+' · '+(v.exam?.name||'任务');tick();}
function payload(el){try{return JSON.parse(el.dataset.payload||'{}')}catch{return {}}}
document.addEventListener('input',ev=>{if(ev.target.id==='score'){const hint=document.getElementById('score-band-hint'),v=Number(ev.target.value);if(hint)hint.textContent=ev.target.value!==''&&Number.isFinite(v)&&v>=0&&v<=100?'本次输入位于示例分段 '+(v<60?'低于60':v<80?'60–79.99':v<90?'80–89.99':'90–100')+'；保存后计入本人分布，无强制人数配额。':'请填写0–100的有效分数。';}});
document.addEventListener('submit',ev=>{const el=ev.target.closest('form[data-form]');if(!el)return;ev.preventDefault();const values=Object.fromEntries(new FormData(el)),data={...payload(el),...values},command=el.dataset.form;for(const id of ['verified','complete','demoConfirmed'])data[id]=!!el.querySelector(`[name="${id}"]:checked`);if(command==='import-roster')data.people=new FormData(el).getAll('people');if(command==='save-assignments')data.assignments=[0,1,2].map(q=>new FormData(el).getAll('assignment-'+q).map(Number));if(command==='verify-local')data.verified=['picture','sound','completeVideo'].every(id=>el.querySelector(`[name="${id}"]:checked`));if(command==='check-device')data.verified=['camera','audio','mirror'].every(id=>el.querySelector(`[name="${id}"]:checked`));if(command==='create-exception')data.q=+(data.q??qValue());execute(command,data);});
document.addEventListener('click',ev=>{const el=ev.target.closest('[data-command],[data-ui]');if(!el||el.disabled)return;const data=payload(el);if(el.dataset.command){execute(el.dataset.command,data);return;}switch(el.dataset.ui){
case'close-dialog':close();break;
case'refresh':note('已读取本场原记录，没有重复创建任务。');break;
case'play':note('当前展示虚构视频画面；真实播放在后续媒体接入时实现。');break;
case'finish':if(execute('finish-record',data).ok&&!preview)setTimeout(()=>{const out=YF.run(actorId,'query-save',{examId,...data});if(out.ok)note(out.message);},700);break;
case'interrupt':modal('登记录制异常',form('interrupt-record',reason('reason','具体异常原因')+notice('保留原片段，异常处理后才重新开始本科。','warning'),'保存异常片段并登记',data));break;
case'upload':if(execute('begin-upload',data).ok&&!preview)setTimeout(()=>{const out=YF.run(actorId,'query-upload',{examId,...data});note(out.message,out.ok?'':'warning');},650);break;
case'save-score':case'save-next':{if(saving)return;const value=document.getElementById('score').value,next=el.dataset.ui==='save-next';saving=true;render();setTimeout(()=>{const out=YF.run(actorId,'save-score',{examId,...data,value});saving=false;if(!out.ok)return note(out.message,'warning');if(next){const e=exam(),nextId=e.roster.find(id=>!e.scores[scoreKey(data.q,id)]);go(nextId?'W06':'W17',nextId?{person:nextId,q:data.q}:{q:data.q});}else note(out.message);},450);break;}
case'correction':execute('create-correction',{...data,value:document.getElementById('score').value,reason:document.getElementById('correction-reason').value});break;
case'publish':modal('确认发布本次结果',`<p>${esc(exam().name)} · ${exam().roster.length}名学员。每人只显示本人三科均分与标注口径的参考总分。</p>${button('确认发布','publish',data,'primary')}`);break;
case'disable-staff':modal('停用工作人员',`<p>请先移交所有未完成的场次岗位和待接收任务，历史记录保留。</p>${button('确认停用','disable-staff',data,'danger')}`);break;
case'reject-transfer':{const reason=document.querySelector('form[data-form="accept-transfer"] [name="reason"]').value;execute('reject-transfer',{...data,reason});break;}
case'switch-post':{const to=actor.group==='recorder'?'invigilator':'recorder',next=Object.values(RolePolicy.actors).find(x=>x.staffId===actor.staffId&&x.group===to);const e=exam();if(e?.current&&['recording','saving'].includes(e.records[e.current]?.stage))return note('当前仍在录制或保存，请完成后切换岗位。','warning');location.href=url(next.home,{as:next.id});break;}
case'export':{const e=exam(),rows=[['学区','学员',...subjects,ExamSpec.totalLabel+'（口径待确认）'],...e.roster.map(p=>[YF.students.find(s=>s.id===p).campus,name(p),...subjects.map((_,q)=>YF.mean(examId,q,p)??'缺评未合分'),totalFor(p)??'缺评不计算'])],blob=new Blob(['\ufeff'+rows.map(r=>r.join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=e.id+'-成绩核对.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);note('核对表已导出，没有发布或改变成绩。');break;}
}});
let enteringScore=false;
root.addEventListener('input',ev=>{if(ev.target.id==='score'){enteringScore=true;YF.run(actorId,'draft-score',{examId,person:ev.target.dataset.scorePerson,q:+ev.target.dataset.scoreQ,value:ev.target.value});renderedState=JSON.stringify(context());enteringScore=false;document.getElementById('score-status').textContent='本机输入已保留，尚未提交';}});
root.addEventListener('change',ev=>{if(ev.target.id==='exam-switch')go(actor.home,{exam:ev.target.value});});
document.addEventListener('click',ev=>{if(saving&&ev.target.closest('a[href]')){ev.preventDefault();note('正在保存本次评分，请等结果后离开。','warning');}},true);
let autoFinishing=false,prepExpiredRendered=false;
function tick(){const timer=document.getElementById('timer');if(timer){const left=Math.max(0,Number(timer.dataset.duration)-(Date.now()-Number(timer.dataset.start))/1000);timer.textContent=ExamSpec.time(left);if(left<=0&&!preview&&!autoFinishing){autoFinishing=true;const r=exam()?.records?.[personId()];if(r?.stage==='recording'&&execute('finish-record',{person:personId(),q:r.subject,auto:true}).ok)setTimeout(()=>{const result=YF.run(actorId,'query-save',{examId,person:personId(),q:r.subject});if(result.ok)note('到时已自动结束并保存，请检查本科视频。');autoFinishing=false;},700);else autoFinishing=false;}}
 document.querySelectorAll('[data-prep-start]').forEach(el=>{const start=Number(el.dataset.prepStart),left=start?Math.max(0,900-(Date.now()-start)/1000):0;el.textContent=ExamSpec.time(left);const state=el.nextElementSibling;if(left<=0&&state)state.textContent='备稿已到时，请等待监考叫号，不自行入场。';if(left<=0&&start&&!prepExpiredRendered){prepExpiredRendered=true;if(screen==='S06')render();}});}

YF.subscribe(()=>{if(!enteringScore&&JSON.stringify(context())!==renderedState)render();});render();if(!preview)setInterval(tick,1000);
window.addEventListener('beforeunload',ev=>{if(exam()?.records?.[personId()]?.stage==='recording'&&!preview){ev.preventDefault();ev.returnValue='';}});
if(parent!==window)parent.postMessage({type:'yf-screen',screen,actor:actorId,exam:examId,fixture:YF.fixture,walk:YF.walk,person:personId(),q:qValue()},'*');
})();
